using Microsoft.AspNetCore.Mvc;using Orchestration.API.Engineering.Contracts;using Orchestration.API.Engineering.Services;
namespace Orchestration.API.Engineering.Controllers;
[ApiController][Route("api/engineering/extractions")]public sealed class EngineeringExtractionController:ControllerBase{readonly IEngineeringExecutionService service;public EngineeringExtractionController(IEngineeringExecutionService service)=>this.service=service;[HttpPost]public IActionResult Post([FromBody]EngineeringExtractionRequest request,CancellationToken token){try{var job=service.StartExtraction(request,token);return AcceptedAtAction(nameof(EngineeringJobsController.Get),"EngineeringJobs",new{jobId=job.JobId},job);}catch(EngineeringValidationException ex){return BadRequest(new{code=ex.Code,message=ex.Message});}}}
